    public static int ttBand(int a0, int a1, int b0, int b1) {
        // 1 when two extents share a band: they overlap by at least half of the smaller.
        int ov = ttMin(a1, b1) - ttMax(a0, b0);
        int sm = ttMin(a1 - a0, b1 - b0);
        if (ov <= 0) {
            return 0;
        }
        if ((ov * 2) >= ttMax(1, sm)) {
            return 1;
        }
        return 0;
    }
